+	if (sw->pvid[port] == vlan->vid) {
+		sw->pvid[port] = TSN_SW_DEFAULT_VID;
+		sw->pvid_untagged[port] = false;
+		xlnx_tsn_apply_pvid(sw, port);
+	}
+
+	return 0;
+}
